CREATE TABLE alertes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, horodatage TIMESTAMP(0), host TEXT, cible TEXT);
CREATE FUNCTION f_trg_ioc() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.domaine IN (SELECT valeur FROM ioc WHERE type = 'domaine') OR NEW.ip_dest IN (SELECT valeur FROM ioc WHERE type = 'ip') THEN
    INSERT INTO alertes (horodatage, host, cible) VALUES (NEW.horodatage, NEW.host, NEW.domaine);
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_ioc AFTER INSERT ON proxy_logs FOR EACH ROW EXECUTE FUNCTION f_trg_ioc();

