CREATE TABLE rejeu (horodatage TIMESTAMP(0), host TEXT, domaine TEXT, ip_dest TEXT);
CREATE TABLE alertes (id INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, horodatage TIMESTAMP(0), host TEXT, cible TEXT);
CREATE FUNCTION f_trg_rejeu() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.domaine IN (SELECT valeur FROM ioc WHERE type = 'domaine') OR NEW.ip_dest IN (SELECT valeur FROM ioc WHERE type = 'ip') THEN
    INSERT INTO alertes (horodatage, host, cible) VALUES (NEW.horodatage, NEW.host, NEW.domaine);
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER trg_rejeu AFTER INSERT ON rejeu FOR EACH ROW EXECUTE FUNCTION f_trg_rejeu();
INSERT INTO rejeu (horodatage, host, domaine, ip_dest) SELECT horodatage, host, domaine, ip_dest FROM proxy_logs ORDER BY horodatage;
SELECT host, MIN(horodatage) AS premiere, COUNT(*) AS alertes FROM alertes GROUP BY host ORDER BY premiere;
